posStyle:
/* 배달앱 사장님용 주문접수 화면식: 민트 머리띠, 왼쪽 신규·처리중·완료 목록, 오른쪽 주문 상세와 큰 접수 버튼 */
:root {
  --mint: #2ac1bc; --mint-press: #1fa9a4; --mint-soft: #e8f8f7;
  --ink: #1e1e1e; --sub: #6f6f6f; --faint: #a0a0a0; --line: #e8e8e8; --gray: #f2f3f5; --white: #ffffff;
  --red: #ef4f56; --orange: #ff7a00; --green-bg: #e7f8ee; --green: #16a05a;
  --f-title: 'Do Hyeon', 'Noto Sans KR', 'Malgun Gothic', sans-serif;
  --f-badge: 'Jua', 'Noto Sans KR', 'Malgun Gothic', sans-serif;
  --f-body: 'Noto Sans KR', 'Malgun Gothic', 'Apple SD Gothic Neo', system-ui, sans-serif;
  color-scheme: light;
}
body { background: var(--gray); color: var(--ink); font-family: var(--f-body); display: grid; grid-template-rows: auto 1fr; height: 100vh; overflow: hidden; }
button { font-family: var(--f-body); color: var(--ink); background: var(--white); border: 1px solid var(--line); }
button:hover { border-color: #cfcfcf; }
button:focus-visible { outline: 2px solid var(--mint-press); outline-offset: 2px; }

header { background: var(--mint); color: #fff; display: flex; align-items: center; gap: 12px; padding: 10px 16px; flex-wrap: wrap; }
header h1 { font-family: var(--f-title); font-weight: 400; font-size: 26px; margin: 0; }
header .demo { font-size: 12px; border: 1px solid rgba(255,255,255,.6); border-radius: 999px; padding: 1px 8px; }
header select { font: inherit; font-size: 15px; color: var(--ink); background: #fff; border: 0; border-radius: 8px; padding: 6px 10px; }
header .open { font-family: var(--f-badge); background: #fff; color: var(--mint-press); border-radius: 999px; padding: 2px 10px; font-size: 14px; }
header .sp { flex: 1; }
header .clock { font-size: 24px; font-weight: 900; font-variant-numeric: tabular-nums; }
.busy { display: flex; align-items: center; gap: 4px; font-size: 14px; }
.busy button { background: rgba(255,255,255,.2); color: #fff; border: 1px solid rgba(255,255,255,.5); border-radius: 8px; padding: 4px 10px; font-size: 14px; }
.busy button.on { background: #fff; color: var(--mint-press); font-weight: 700; }
.busy button:disabled { opacity: .5; }

main { display: grid; grid-template-columns: minmax(280px, 380px) minmax(0, 1fr); gap: 0; min-height: 0; }
.left { background: var(--white); border-right: 1px solid var(--line); display: grid; grid-template-rows: auto 1fr auto; min-height: 0; }
.tabs { display: grid; grid-template-columns: repeat(3, 1fr); border-bottom: 1px solid var(--line); }
.tabs button { border: 0; border-radius: 0; background: transparent; padding: 14px 6px 11px; font-size: 17px; color: var(--sub); border-bottom: 3px solid transparent; }
.tabs button.on { color: var(--ink); font-weight: 900; border-bottom-color: var(--mint); }
.tabs .n { font-family: var(--f-badge); display: inline-grid; place-items: center; min-width: 22px; height: 22px; border-radius: 11px; padding: 0 6px; margin-left: 4px; font-size: 13px; background: var(--gray); color: var(--sub); }
.tabs .n.hot { background: var(--red); color: #fff; }
.list { overflow: auto; min-height: 0; }
.item { display: grid; gap: 4px; width: 100%; text-align: left; border: 0; border-bottom: 1px solid var(--line); border-radius: 0; padding: 14px 16px; background: #fff; }
.item.sel { background: var(--mint-soft); box-shadow: inset 4px 0 0 var(--mint); }
.item .r1 { display: flex; align-items: center; gap: 8px; }
.item .tm { font-size: 20px; font-weight: 900; font-variant-numeric: tabular-nums; }
.item .r2 { font-size: 15px; }
.item .r3 { font-size: 13px; color: var(--sub); display: flex; gap: 6px; flex-wrap: wrap; align-items: center; }
.item .st { margin-left: auto; font-size: 13px; color: var(--sub); }
.new-dot { font-family: var(--f-badge); background: var(--red); color: #fff; border-radius: 4px; padding: 0 6px; font-size: 13px; animation: blink 1s steps(2, start) 6; }
.mode { font-family: var(--f-badge); font-size: 14px; border-radius: 4px; padding: 0 6px; }
.mode.DELIVERY { color: var(--mint-press); background: var(--mint-soft); }
.mode.PICKUP { color: var(--orange); background: #fff2e5; }
.plate { font-weight: 900; letter-spacing: .03em; background: var(--ink); color: #fff; border-radius: 4px; padding: 0 6px; font-size: 13px; }
.here { font-family: var(--f-badge); color: var(--green); background: var(--green-bg); border-radius: 4px; padding: 0 6px; font-size: 13px; }
.empty { color: var(--faint); padding: 28px 16px; text-align: center; font-size: 15px; }
.waiting { border-top: 1px dashed var(--line); padding: 10px 16px 12px; font-size: 13px; color: var(--sub); background: #fafafa; }
.waiting b { color: var(--ink); }
.waiting .w { display: flex; gap: 8px; padding: 3px 0; font-variant-numeric: tabular-nums; }

.detail { overflow: auto; min-height: 0; padding: 16px; display: grid; gap: 12px; align-content: start; }
.card { background: var(--white); border-radius: 12px; padding: 16px 18px; }
.d-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.d-head .mode { font-size: 18px; padding: 2px 10px; }
.d-head h2 { font-family: var(--f-title); font-weight: 400; font-size: 30px; margin: 0; }
.d-head .id { margin-left: auto; color: var(--faint); font-size: 13px; }
.arrived { display: flex; align-items: center; gap: 10px; background: var(--green-bg); color: var(--green); border-radius: 10px; padding: 12px 14px; font-size: 18px; font-weight: 900; }
.kv { display: grid; grid-template-columns: auto 1fr; gap: 8px 18px; font-size: 16px; }
.kv span:nth-child(odd) { color: var(--sub); }
.kv b { font-variant-numeric: tabular-nums; }
.kv .big { font-size: 22px; }
.moved { color: var(--orange); font-size: 14px; }
.lines .ln { display: flex; gap: 10px; padding: 9px 0; border-bottom: 1px solid var(--line); font-size: 18px; }
.lines .ln:last-child { border-bottom: 0; }
.lines .ln .nm { flex: 1; min-width: 0; font-weight: 700; }
.lines .ln .nm small { display: block; color: var(--sub); font-weight: 400; font-size: 14px; }
.lines .ln .q { font-weight: 900; width: 40px; text-align: center; }
.lines .ln .p { width: 100px; text-align: right; font-variant-numeric: tabular-nums; }
.sum { display: flex; justify-content: space-between; font-size: 16px; padding: 3px 0; font-variant-numeric: tabular-nums; }
.sum.total { font-size: 20px; font-weight: 900; border-top: 1px solid var(--line); margin-top: 6px; padding-top: 10px; }
.paid { font-size: 14px; color: var(--sub); margin-top: 6px; }
.actions { display: grid; grid-template-columns: 1fr 2fr; gap: 10px; }
.actions button { padding: 18px; font-size: 20px; border-radius: 12px; font-weight: 700; }
.actions .go { background: var(--mint); border-color: var(--mint); color: #fff; }
.actions .go:hover { background: var(--mint-press); }
.actions .done { background: var(--gray); color: var(--sub); border-color: var(--line); grid-column: 1 / -1; }
.note { font-size: 13px; color: var(--sub); }
.flash { animation: pop 1.4s ease-out 3; }
@keyframes pop { 0% { box-shadow: 0 0 0 0 rgba(42,193,188,.6); } 70% { box-shadow: 0 0 0 14px rgba(42,193,188,0); } }
@keyframes blink { to { visibility: hidden; } }
@media (prefers-reduced-motion: reduce) { .new-dot, .flash { animation: none; } }
@media (max-width: 760px) {
  body { height: auto; overflow: auto; }
  main { grid-template-columns: 1fr; }
  .left { border-right: 0; }
  .list { max-height: 320px; }
}
.conn { color: var(--sub); }
